using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea.BattleActions;

public class RunesPanelInitializer : MonoBehaviour
{
	[Header("Virtues Using")]
	[SerializeField]
	private bool virtuesMoreThanOneUsePerTurn;

	[Header("Runes Positioning")]
	[SerializeField]
	private Transform[] runePositions;

	[Header("Components")]
	[SerializeField]
	private GameObject runeInstancePrefab;

	[SerializeField]
	private Transform runesHolder;

	[SerializeField]
	private Image playerAvatar;

	[SerializeField]
	private RunesPanel runesPanel;

	[Header("Assets")]
	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private List<RuneInstance> runeInstances;

	[SerializeField]
	private Rune[] runes;

	public PlayerCurrentRunes PlayerCurrentRunes => playerCurrentRunes;

	public List<RuneInstance> RuneInstances => runeInstances;

	public Rune[] Runes => runes;

	public void Initialize(Rune[] newRunes = null)
	{
		if (newRunes == null)
		{
			playerCurrentRunes.OnReset();
			runes = playerCurrentRunes.Runes;
		}
		else
		{
			runes = newRunes;
		}
		runeInstances = runesPanel.runeInstances;
		InitializePlayerAvatar();
		runesPanel.Initialize();
		PopulateRuneInstances();
	}

	public void InitializePlayerAvatar()
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.AvatarSprite != null)
		{
			playerAvatar.sprite = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.AvatarSprite;
		}
	}

	public void PopulateRuneInstances()
	{
		for (int i = 0; i < runes.Length; i++)
		{
			runes[i].index = i;
			if (runes[i].BattleAction != null)
			{
				SpawnActionSlot(i, replaceNullWithNewRuneInstance: false);
			}
			else
			{
				runeInstances.Add(null);
			}
		}
	}

	private void SpawnActionSlot(int i, bool replaceNullWithNewRuneInstance)
	{
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(runeInstancePrefab.name, runesHolder);
		@object.transform.position = runePositions[i].position.ZeroZ();
		RuneInstance component = @object.GetComponent<RuneInstance>();
		component.Initialize(runes[i], runesPanel, i == 0);
		if (replaceNullWithNewRuneInstance)
		{
			runeInstances[i] = component;
		}
		else
		{
			runeInstances.Add(component);
		}
	}

	public void InitializeBattle()
	{
		playerCurrentRunes.ResetUsedActiveAndRefreshedRunes();
	}

	public void StorageRuneInstances()
	{
		for (int i = 0; i < runeInstances.Count; i++)
		{
			if (runeInstances[i] != null)
			{
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(runeInstances[i].gameObject);
			}
		}
		runeInstances.Clear();
	}

	public void OnToggleMultipleUseRune(bool value)
	{
		virtuesMoreThanOneUsePerTurn = value;
	}

	public void AddNewRune(BattleAction battleAction, int actionValue, int newRuneIndex)
	{
		SetRune(battleAction, actionValue, newRuneIndex);
		SpawnActionSlot(newRuneIndex, replaceNullWithNewRuneInstance: true);
	}

	public void ReplaceRuneWithNewRune(BattleAction battleAction, int actionValue, int replaceRuneIndex, bool dontModifyNonShuffledRunes = false)
	{
		SetRune(battleAction, actionValue, replaceRuneIndex, dontModifyNonShuffledRunes);
		ReplaceActionSlotAction(replaceRuneIndex);
	}

	private void SetRune(BattleAction battleAction, int actionValue, int index, bool dontModifyNonShuffledRunes = false)
	{
		runes[index].BattleAction = battleAction;
		runes[index].ActionValue = actionValue;
		runes[index].index = index;
		if (!dontModifyNonShuffledRunes)
		{
			SetRuneNonShuffledRunes(battleAction, actionValue, index);
		}
	}

	public void SetRuneNonShuffledRunes(BattleAction battleAction, int actionValue, int index)
	{
		playerCurrentRunes.NonShuffledRunes[index].BattleAction = battleAction;
		playerCurrentRunes.NonShuffledRunes[index].ActionValue = actionValue;
		playerCurrentRunes.NonShuffledRunes[index].index = index;
	}

	private void ReplaceActionSlotAction(int i)
	{
		RuneInstance runeInstance = runeInstances[i];
		if (runes[i].BattleAction == null)
		{
			if (runeInstance != null)
			{
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(runeInstance.gameObject);
				runeInstances[i] = null;
			}
			runesPanel.DisableRuneSlotSprite(i);
		}
		else if (runeInstance == null)
		{
			SpawnActionSlot(i, replaceNullWithNewRuneInstance: true);
		}
		else
		{
			runeInstance.Initialize(runes[i], runesPanel, i == 0);
		}
	}

	public void GoBackToOldRune(Rune rune)
	{
		SetRune(rune.BattleAction, rune.ActionValue, rune.index);
		for (int i = 0; i < runes.Length; i++)
		{
			runes[i].index = i;
			ReplaceActionSlotAction(i);
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(this, 4, delegate
		{
			runesPanel.OnUpdatePlayerCorruption();
		});
	}

	public void ShuffleVirtues()
	{
		ResetRunesToNonShuffledRunes();
		runes.Shuffle();
		for (int i = 0; i < runes.Length; i++)
		{
			runes[i].index = i;
			ReplaceActionSlotAction(i);
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(this, 4, delegate
		{
			runesPanel.OnUpdatePlayerCorruption();
		});
	}

	public void ResetRunesToNonShuffledRunes()
	{
		for (int i = 0; i < runes.Length; i++)
		{
			runes[i].BattleAction = playerCurrentRunes.NonShuffledRunes[i].BattleAction;
			runes[i].ActionValue = playerCurrentRunes.NonShuffledRunes[i].ActionValue;
			runes[i].index = playerCurrentRunes.NonShuffledRunes[i].index;
		}
	}
}
